package com.lifeos.projects;import com.lifeos.shared.AuditableEntity;import com.lifeos.users.User;import jakarta.persistence.*;import java.time.*;@Entity@Table(name="projects")public class Project extends AuditableEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=200)private String name;@Column(columnDefinition="text")private String description;@Enumerated(EnumType.STRING)@Column(nullable=false)private ProjectStatus status;private LocalDate startDate;private LocalDate targetDate;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public ProjectStatus getStatus(){return status;}public void setStatus(ProjectStatus v){status=v;}public LocalDate getStartDate(){return startDate;}public void setStartDate(LocalDate v){startDate=v;}public LocalDate getTargetDate(){return targetDate;}public void setTargetDate(LocalDate v){targetDate=v;}public void setUser(User v){user=v;}}
